-- migrate:no-transaction
-- Step 2 of 6 for orders.public_id: fill in existing rows.
--
-- Runs without a transaction so the procedure below can COMMIT after every batch. Each batch
-- holds row locks on at most batch_size rows, and only until that batch commits. Nothing takes a
-- table-level lock beyond ROW EXCLUSIVE, so reads and writes on orders are not blocked.
--
-- Batches walk the primary key (last_id), so each batch is an index range scan. No batch
-- re-scans rows already filled in. The loop ends when no id above last_id remains. Rows inserted
-- after 0004 already get a default value, so no NULLs can appear behind the cursor. The
-- procedure is recreated on re-run, and the WHERE public_id IS NULL filter makes it safe to
-- re-run after a partial failure.
SET lock_timeout = '5s';

CREATE OR REPLACE PROCEDURE orders_backfill_public_id(batch_size int DEFAULT 5000)
LANGUAGE plpgsql
AS $$
DECLARE
  last_id bigint := 0;
  upper_id bigint;
BEGIN
  LOOP
    SELECT max(id) INTO upper_id
    FROM (SELECT id FROM orders WHERE id > last_id ORDER BY id LIMIT batch_size) AS batch;
    EXIT WHEN upper_id IS NULL;

    -- Plain row locks (no SKIP LOCKED): a row held by an app transaction is waited for, so no
    -- row is skipped and the loop can end only when the table is covered.
    UPDATE orders
    SET public_id = gen_random_uuid()
    WHERE id > last_id AND id <= upper_id AND public_id IS NULL;

    last_id := upper_id;
    COMMIT;
  END LOOP;
END
$$;

CALL orders_backfill_public_id();
DROP PROCEDURE orders_backfill_public_id(int);
RESET lock_timeout;

