-- migrate:no-transaction
-- Step 3 of 6 for orders.public_id: build the unique index without blocking writes.
--
-- CREATE INDEX CONCURRENTLY cannot run inside a transaction. It takes only SHARE UPDATE EXCLUSIVE,
-- which does not block reads or writes. If a build fails it leaves an INVALID index behind, so the
-- file drops any leftover index first; that makes a re-run safe.
SET lock_timeout = '5s';

DROP INDEX CONCURRENTLY IF EXISTS orders_public_id_key;
CREATE UNIQUE INDEX CONCURRENTLY orders_public_id_key ON orders (public_id);

RESET lock_timeout;

