import assert from 'node:assert/strict'
import { copyFile, mkdtemp } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { test } from 'node:test'
import { PGlite } from '@electric-sql/pglite'
import { migrate } from '../src/migrate.ts'
import { createOrder } from '../src/orders.ts'

const MIGRATIONS = 'migrations'

/** A directory holding only the first `count` migrations, to simulate an older database. */
async function firstMigrations(count: number): Promise<string> {
  const { readdir } = await import('node:fs/promises')
  const dir = await mkdtemp(join(tmpdir(), 'migrations-'))
  const files = (await readdir(MIGRATIONS)).filter((f) => f.endsWith('.sql')).sort()
  for (const file of files.slice(0, count)) await copyFile(join(MIGRATIONS, file), join(dir, file))
  return dir
}

