test('re-running the backfill after a partial run fills only the remaining NULLs', async () => {
  const db = new PGlite()
  await migrate(db, await firstMigrations(4))
  await db.query(`INSERT INTO customers (email, name) VALUES ('bo@example.com', 'Bo')`)
  await db.query(`INSERT INTO orders (customer_id, total_cents) SELECT 1, 1 FROM generate_series(1, 300)`)
  // Simulate a partially filled table: the first 100 rows already have an id.
  await db.query(`UPDATE orders SET public_id = gen_random_uuid() WHERE id <= 100`)
  const kept = await db.query(`SELECT id, public_id FROM orders WHERE id <= 100 ORDER BY id`)

  await migrate(db, MIGRATIONS)

  const kept2 = await db.query(`SELECT id, public_id FROM orders WHERE id <= 100 ORDER BY id`)
  assert.deepEqual(kept2.rows, kept.rows, 'existing public_ids are not regenerated')
  const { rows } = await db.query(`SELECT count(*)::int AS n FROM orders WHERE public_id IS NULL`)
  assert.equal((rows[0] as { n: number }).n, 0)
})

